        'Other revenue':{ t:'$255M of other network assessments', h:'<p>Other network assessments were $255 million in the quarter.</p>' },
        'VAS revenue':{ t:'+22%, 19% excluding acquisitions', h:'<p>VAS grew 22%, with about 3 points from Recorded Future and Minna and 19% organic, on security, digital and authentication, consumer acquisition and engagement and business and market insights, plus pricing.</p>' },
        'Payment network revenue':{ t:'+10% cc', h:'<p>Payment Network net revenue grew 10%, on domestic and cross-border volume and transactions, including growth in rebates and incentives.</p>' }
